import{_ as t,o as i,c as r,a2 as o}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"Memory System","description":"The five memory types of Hearth Memory OS, record structure, write and retrieval, budgets, conflicts, forgetting, poisoning defenses, and synchronization.","frontmatter":{"title":"Memory System","description":"The five memory types of Hearth Memory OS, record structure, write and retrieval, budgets, conflicts, forgetting, poisoning defenses, and synchronization.","outline":[2,3]},"headers":[],"relativePath":"en/architecture/memory.md","filePath":"en/architecture/memory.md","lastUpdated":1793706118000}'),a={name:"en/architecture/memory.md"};function n(s,e,l,d,c,m){return i(),r("div",null,[...e[0]||(e[0]=[o('<p class="eyebrow">MEMORY OS</p><h1 id="memory-system" tabindex="-1">Memory System <a class="header-anchor" href="#memory-system" aria-label="Permalink to &quot;Memory System&quot;">​</a></h1><p class="lead">Memory is not chat history; it is a constrained judgment cache. It must have provenance, confidence, sensitivity, conflict handling, and a forgetting policy.</p><h2 id="memory-os" tabindex="-1">Memory OS <a class="header-anchor" href="#memory-os" aria-label="Permalink to &quot;Memory OS&quot;">​</a></h2><p>Memory is not chat history, and more is not better. It is a &quot;constrained judgment cache&quot; that must be explainable, correctable, and forgettable.</p><h3 id="five-types-of-memory" tabindex="-1">Five types of memory <a class="header-anchor" href="#five-types-of-memory" aria-label="Permalink to &quot;Five types of memory&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Content</th><th>Lifecycle</th><th>Purpose</th></tr></thead><tbody><tr><td>Working Memory</td><td>Current goals, constraints, steps, and temporary observations</td><td>Cleared when the Task ends</td><td>Task Pack, current plan</td></tr><tr><td>Episodic Memory</td><td>Past Tasks, results, failures, human corrections</td><td>Medium-term, summarizable</td><td>&quot;How was a similar Task handled last time&quot;</td></tr><tr><td>Semantic Memory</td><td>People, projects, organizations, facts, relationships</td><td>Long-term, requires provenance and validity period</td><td>Project background, contacts, decisions</td></tr><tr><td>User Model</td><td>Preferences, communication style, boundaries, habits, value ordering</td><td>Long-term, highly editable</td><td>Reduce repeated explanations</td></tr><tr><td>Procedural Memory</td><td>Skills, workflows, tool recipes, validators</td><td>Versioned, rollback-capable</td><td>Reuse for repeated Tasks, Evolution</td></tr></tbody></table><p>A Skill includes permissions, versioning, evaluation, and rollback metadata; Memory only stores &quot;experience that was once valid.&quot;</p><h3 id="memory-records" tabindex="-1">Memory records <a class="header-anchor" href="#memory-records" aria-label="Permalink to &quot;Memory records&quot;">​</a></h3><p>Each memory contains at least:</p><ul><li>id, type, subject, statement;</li><li>scope (user, project, person, device);</li><li>sourceRefs and sourceTrust;</li><li>confidence, sensitivity;</li><li>createdAt, lastUsedAt, expiresAt;</li><li>supersedes, conflictsWith;</li><li>status: quarantined / active / superseded / forgotten;</li><li>forgetPolicy.</li></ul><p>The key is not having many fields, but that every memory can answer: where it came from, how trustworthy it is, who can see it, when it expires, which memory it conflicts with, and how the user can correct or delete it.</p><h3 id="writing-and-retrieval" tabindex="-1">Writing and retrieval <a class="header-anchor" href="#writing-and-retrieval" aria-label="Permalink to &quot;Writing and retrieval&quot;">​</a></h3><p>Memory writing is not &quot;if the model says it&#39;s worth remembering, remember it.&quot; It should first enter a candidate area, where provenance, sensitivity, duplication, conflict, and user authorization are checked; highly sensitive content is not written automatically by default.</p><p>Retrieval filters by Task needs, scope, source trustworthiness, recency, sensitivity, and Token budget; it must not stuff all memories into context, nor allow different projects/accounts to contaminate each other.</p><h3 id="memory-budget" tabindex="-1">Memory budget <a class="header-anchor" href="#memory-budget" aria-label="Permalink to &quot;Memory budget&quot;">​</a></h3><ul><li>Total memory volume budget;</li><li>Per-record length budget;</li><li>Context injection budget;</li><li>Recall frequency and decay;</li><li>Expiration and archiving.</li></ul><p>The memory budget is linked with the Token Governor to avoid the illusion that &quot;the more memory, the smarter.&quot;</p><h3 id="conflict-updates-and-confidence" tabindex="-1">Conflict, updates, and confidence <a class="header-anchor" href="#conflict-updates-and-confidence" aria-label="Permalink to &quot;Conflict, updates, and confidence&quot;">​</a></h3><ul><li>New facts must not silently overwrite old facts;</li><li>Preserve provenance and time;</li><li>Mark conflicts or request user confirmation;</li><li>Low-confidence memories must not independently trigger high-risk actions;</li><li>Explicit user corrections take priority;</li><li>Expired facts can be downweighted or forgotten.</li></ul><h3 id="forgetting" tabindex="-1">Forgetting <a class="header-anchor" href="#forgetting" aria-label="Permalink to &quot;Forgetting&quot;">​</a></h3><p>Forgetting must propagate to indexes, caches, device copies, and derived summaries. The user should be able to confirm:</p><ul><li>what was forgotten;</li><li>why it was forgotten;</li><li>which devices and indexes have been updated;</li><li>whether it still exists in backups;</li><li>how to verify.</li></ul><h3 id="memory-poisoning-and-prompt-injection" tabindex="-1">Memory poisoning and prompt injection <a class="header-anchor" href="#memory-poisoning-and-prompt-injection" aria-label="Permalink to &quot;Memory poisoning and prompt injection&quot;">​</a></h3><p>Web pages, emails, documents, and external tool outputs are all untrusted sources. They can become candidate memories, but must not directly gain high trustworthiness, and certainly must not expand permissions through memory. Highly sensitive or externally untrusted content should be quarantined, downweighted, or rejected from being written.</p><h3 id="multi-device-sync-and-ui" tabindex="-1">Multi-device sync and UI <a class="header-anchor" href="#multi-device-sync-and-ui" aria-label="Permalink to &quot;Multi-device sync and UI&quot;">​</a></h3><ul><li>Synced memories must carry version, provenance, and tombstones;</li><li>Deletions must not &quot;resurrect&quot; on another device;</li><li>Sensitive memories are filtered by device scope;</li><li>The memory browser shows &quot;what was remembered, why it was recalled, where it came from&quot;;</li><li>Users can correct, delete, and export;</li><li>&quot;Why it was recalled&quot; must not be explained by the model alone; it needs provenance and rule evidence.</li></ul><h3 id="memory-metrics" tabindex="-1">Memory metrics <a class="header-anchor" href="#memory-metrics" aria-label="Permalink to &quot;Memory metrics&quot;">​</a></h3><ul><li>Recall accuracy;</li><li>Rework caused by incorrect memories;</li><li>User correction rate;</li><li>Forgetting compliance rate;</li><li>Injected Tokens and latency;</li><li>Block rate of sensitive information leakage attempts.</li></ul>',29)])])}const y=t(a,[["render",n]]);export{h as __pageData,y as default};
